INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1cde0a360f37a32bbe512'),'ba43e10e-0562-4f71-bd74-081807cf9c4a','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','80','completed','Korbyn has a lot of what it takes to be a good technician. He is fast and focused with his installs, not producing the cleanest work I''ve ever seen, but certainly above "par" for quality and he is able to lock in and complete them efficiently. Unfortunately, he seems to have issues taking personal responsibility for failure, especially when he misses his alarm and fails to show up to the job at the scheduled time. He has been coached aggressively on this specific point, and seems to be getting to work early now. We will continue to monitor Korbyn, but he could be a great tech if he matures a little more.','2026-03-23T23:33:52.668Z','2026-03-23T23:33:52.743000','2026-03-23T23:33:52.743000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T23:33:52.668Z','69c1cde0a360f37a32bbe512','699b6a243fbe7d5b428f582f','68a6388cc778ad7fe64526ca','{"score":"80","notes":"Korbyn has a lot of what it takes to be a good technician. He is fast and focused with his installs, not producing the cleanest work I''ve ever seen, but certainly above \"par\" for quality and he is able to lock in and complete them efficiently. Unfortunately, he seems to have issues taking personal responsibility for failure, especially when he misses his alarm and fails to show up to the job at the scheduled time. He has been coached aggressively on this specific point, and seems to be getting to work early now. We will continue to monitor Korbyn, but he could be a great tech if he matures a little more.","technicianId":"699b6a243fbe7d5b428f582f","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T23:33:52.668Z","qcUserName":"Ryan Miller","id":"69c1cde0a360f37a32bbe512","created_date":"2026-03-23T23:33:52.743000","updated_date":"2026-03-23T23:33:52.743000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1ccddaba98c8872ec0151'),'dd5f864e-c8be-4bc3-9c29-07d5578ef0e7','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','100','completed','Calvin (goes by Ryan) is going to be an excellent technician I think. He was one of the first technicians on site every day in Missouri, and always showed up ready to work. He is very organized, and well equipped for the job. Ryan doesn''t socialize much, preferring to keep his head down and work. I have high hopes for him.','2026-03-23T23:29:33.440Z','2026-03-23T23:29:33.519000','2026-03-23T23:29:33.519000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T23:29:33.440Z','69c1ccddaba98c8872ec0151','699b6a7a22ef2111ace92d47','68a6388cc778ad7fe64526ca','{"score":"100","notes":"Calvin (goes by Ryan) is going to be an excellent technician I think. He was one of the first technicians on site every day in Missouri, and always showed up ready to work. He is very organized, and well equipped for the job. Ryan doesn''t socialize much, preferring to keep his head down and work. I have high hopes for him.","technicianId":"699b6a7a22ef2111ace92d47","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T23:29:33.440Z","qcUserName":"Ryan Miller","id":"69c1ccddaba98c8872ec0151","created_date":"2026-03-23T23:29:33.519000","updated_date":"2026-03-23T23:29:33.519000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1cc12c70660258f1c02f1'),'e2fa3b84-b2bd-43cf-a22f-8a30a5c8c5e9','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','90','completed','I caught up with Bobby when he was shadowing Robert for Amazon Victorinox. Bobby seems well spoken with a friendly disposition. Getting keys was difficult that night, so he got to see firsthand how to escalate issues like that to the project team. He was very patient when informing the project team, and given the number of delays that can pop up on the Amazon jobs, I think this will serve him well. Robert was the previous technician in Bobby''s Amazon territory, and was able to provide him unique insight into staying and working out there long term.','2026-03-23T23:26:10.323Z','2026-03-23T23:26:10.585000','2026-03-23T23:26:10.585000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T23:26:10.323Z','69c1cc12c70660258f1c02f1','69827c4a2ab5d0d9c9e9576a','68a6388cc778ad7fe64526ca','{"score":"90","notes":"I caught up with Bobby when he was shadowing Robert for Amazon Victorinox. Bobby seems well spoken with a friendly disposition. Getting keys was difficult that night, so he got to see firsthand how to escalate issues like that to the project team. He was very patient when informing the project team, and given the number of delays that can pop up on the Amazon jobs, I think this will serve him well. Robert was the previous technician in Bobby''s Amazon territory, and was able to provide him unique insight into staying and working out there long term.","technicianId":"69827c4a2ab5d0d9c9e9576a","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T23:26:10.323Z","qcUserName":"Ryan Miller","id":"69c1cc12c70660258f1c02f1","created_date":"2026-03-23T23:26:10.585000","updated_date":"2026-03-23T23:26:10.585000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c9cf80afd1d9f38abb0b'),'fe33d54c-9c91-4fd9-a988-8e5992fc9489','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','100','completed','Erik came up to Missouri to help kick off the Walmart printer installs. Erik continues to be a great role model for the newer technicians. He was early to site every day and usually the first one walking in the door. He helped Chance and I track down our site contact and get our equipment and workspace secured. He was very patient showing the technicians the first install and answering any questions.','2026-03-23T23:16:31.446Z','2026-03-23T23:16:31.548000','2026-03-23T23:16:31.548000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T23:16:31.446Z','69c1c9cf80afd1d9f38abb0b','68a6390dc778ad7fe6452705','68a6388cc778ad7fe64526ca','{"score":"100","notes":"Erik came up to Missouri to help kick off the Walmart printer installs. Erik continues to be a great role model for the newer technicians. He was early to site every day and usually the first one walking in the door. He helped Chance and I track down our site contact and get our equipment and workspace secured. He was very patient showing the technicians the first install and answering any questions.","technicianId":"68a6390dc778ad7fe6452705","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T23:16:31.446Z","qcUserName":"Ryan Miller","id":"69c1c9cf80afd1d9f38abb0b","created_date":"2026-03-23T23:16:31.548000","updated_date":"2026-03-23T23:16:31.548000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c9367496ab518e948efc'),'ddbf33e4-81b1-4669-8970-48239e289431','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','100','completed','I had the pleasure of joining Joseph for his first week of shadowing for Summit Schools. Joe is clearly very intelligent, and mechanically inclined on top of that. He builds race cars with a friend of his in his spare time, and is able to translate that skillset over to what we do very well. He was itching to get busy, so we had him start his own installs on the second day. He learns quickly, doesn''t ask the same question twice, and has a good set of tools to get started with. I think Joseph will make a great member of our team.','2026-03-23T23:13:58.175Z','2026-03-23T23:13:58.254000','2026-03-23T23:13:58.254000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T23:13:58.175Z','69c1c9367496ab518e948efc','69b1a557a3b954d3094807ea','68a6388cc778ad7fe64526ca','{"score":"100","notes":"I had the pleasure of joining Joseph for his first week of shadowing for Summit Schools. Joe is clearly very intelligent, and mechanically inclined on top of that. He builds race cars with a friend of his in his spare time, and is able to translate that skillset over to what we do very well. He was itching to get busy, so we had him start his own installs on the second day. He learns quickly, doesn''t ask the same question twice, and has a good set of tools to get started with. I think Joseph will make a great member of our team.","technicianId":"69b1a557a3b954d3094807ea","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T23:13:58.175Z","qcUserName":"Ryan Miller","id":"69c1c9367496ab518e948efc","created_date":"2026-03-23T23:13:58.254000","updated_date":"2026-03-23T23:13:58.254000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c91685b4db94ca069905'),'b6c62a58-1410-4cc1-ba16-96d3d4991ad7','b599d2c9-da21-4dc4-b77f-77473fa8f75c','100','completed','Lane seems like a really nice guy and fairly intelligent, met up with him recently and spent a while with him and he seems to enjoy the job and has nothing to complain about. ','2026-03-23T23:13:25.979Z','2026-03-23T23:13:26.452000','2026-03-23T23:13:26.452000','b599d2c9-da21-4dc4-b77f-77473fa8f75c','Chance Hoffman','2026-03-23T23:13:25.979Z','69c1c91685b4db94ca069905','68b1ddb952361a61a2e13227','68a63874fca958620f9e640e','{"score":"100","notes":"Lane seems like a really nice guy and fairly intelligent, met up with him recently and spent a while with him and he seems to enjoy the job and has nothing to complain about. ","technicianId":"68b1ddb952361a61a2e13227","qcUserId":"68a63874fca958620f9e640e","inspectionDate":"2026-03-23T23:13:25.979Z","qcUserName":"Chance Hoffman","id":"69c1c91685b4db94ca069905","created_date":"2026-03-23T23:13:26.452000","updated_date":"2026-03-23T23:13:26.452000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c8649bb2bfdefec4836c'),'4a42b659-91c3-49ce-9b6d-14cbea1eb8bc','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','85','completed','Rance has turned into a dependable technician for us. He shows up on time and begins working quickly, with no regard for the difficulty of installation. His communication skills are still weak, but Rance is willing to stay late to get the job done, and rarely misses quota at this point. I don''t get the feeling he is a big fan of Matt Bailey, but with the way the site is laid out, they almost never have to interact anymore, and he is more interested in finishing the customer site than causing friction.','2026-03-23T23:10:28.032Z','2026-03-23T23:10:28.464000','2026-03-23T23:10:28.464000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T23:10:28.032Z','69c1c8649bb2bfdefec4836c','68a63bd2ccc87b9523363bc6','68a6388cc778ad7fe64526ca','{"score":"85","notes":"Rance has turned into a dependable technician for us. He shows up on time and begins working quickly, with no regard for the difficulty of installation. His communication skills are still weak, but Rance is willing to stay late to get the job done, and rarely misses quota at this point. I don''t get the feeling he is a big fan of Matt Bailey, but with the way the site is laid out, they almost never have to interact anymore, and he is more interested in finishing the customer site than causing friction.","technicianId":"68a63bd2ccc87b9523363bc6","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T23:10:28.032Z","qcUserName":"Ryan Miller","id":"69c1c8649bb2bfdefec4836c","created_date":"2026-03-23T23:10:28.464000","updated_date":"2026-03-23T23:10:28.464000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c72eceb9dc9c5a191f3e'),'23a86ea8-3863-4e7f-b512-4035a3c43671','b599d2c9-da21-4dc4-b77f-77473fa8f75c','100','completed','Kicked off the new Walmart job with them last week and spent the week with them. Nate is actually happy to be doing something a little different than lockers for now and I think he really likes this contract and is going to enjoy it for its duration. He’s a good match for this contract coming off lockers. ','2026-03-23T23:05:18.741Z','2026-03-23T23:05:18.900000','2026-03-23T23:05:18.900000','b599d2c9-da21-4dc4-b77f-77473fa8f75c','Chance Hoffman','2026-03-23T23:05:18.741Z','69c1c72eceb9dc9c5a191f3e','68a63bbbce4a441a4bad0e20','68a63874fca958620f9e640e','{"score":"100","notes":"Kicked off the new Walmart job with them last week and spent the week with them. Nate is actually happy to be doing something a little different than lockers for now and I think he really likes this contract and is going to enjoy it for its duration. He\u2019s a good match for this contract coming off lockers. ","technicianId":"68a63bbbce4a441a4bad0e20","qcUserId":"68a63874fca958620f9e640e","inspectionDate":"2026-03-23T23:05:18.741Z","qcUserName":"Chance Hoffman","id":"69c1c72eceb9dc9c5a191f3e","created_date":"2026-03-23T23:05:18.900000","updated_date":"2026-03-23T23:05:18.900000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c6f9ee51d74c2c8c05f3'),'86026ccd-4748-4ee7-9d5d-a74840848b0e','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','70','completed','Matthew is good about arriving to the jobsite early, and maintaining excellent communication with his project team. He knows these installs well and is very thorough with them, rarely having to go back for fixes. I have to say that he is a bit disorganized, having to go to and from his vehicle, the shop, and the asset he is working on. I offered a few suggestions to that end, and helped clarify some instructions for him that should allow for more production moving forward.','2026-03-23T23:04:24.958Z','2026-03-23T23:04:25.120000','2026-03-23T23:04:25.120000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T23:04:24.958Z','69c1c6f9ee51d74c2c8c05f3','68a63b7597298019b3a8e8c0','68a6388cc778ad7fe64526ca','{"score":"70","notes":"Matthew is good about arriving to the jobsite early, and maintaining excellent communication with his project team. He knows these installs well and is very thorough with them, rarely having to go back for fixes. I have to say that he is a bit disorganized, having to go to and from his vehicle, the shop, and the asset he is working on. I offered a few suggestions to that end, and helped clarify some instructions for him that should allow for more production moving forward.","technicianId":"68a63b7597298019b3a8e8c0","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T23:04:24.958Z","qcUserName":"Ryan Miller","id":"69c1c6f9ee51d74c2c8c05f3","created_date":"2026-03-23T23:04:25.120000","updated_date":"2026-03-23T23:04:25.120000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c6263172b763cbdc78e2'),'0d2595b1-c405-4362-9b96-980221141db3','b599d2c9-da21-4dc4-b77f-77473fa8f75c','100','completed','Rapha is always at the top of the list of guys that can just pick up a job and run with it. Was with him and Eric Jr on site recently and between the two of them they make a great team and do very good work and both seem to genuinely care about their quality and production. ','2026-03-23T23:00:53.797Z','2026-03-23T23:00:54.113000','2026-03-23T23:00:54.113000','b599d2c9-da21-4dc4-b77f-77473fa8f75c','Chance Hoffman','2026-03-23T23:00:53.797Z','69c1c6263172b763cbdc78e2','68a63be4f1c931819459b8f0','68a63874fca958620f9e640e','{"score":"100","notes":"Rapha is always at the top of the list of guys that can just pick up a job and run with it. Was with him and Eric Jr on site recently and between the two of them they make a great team and do very good work and both seem to genuinely care about their quality and production. ","technicianId":"68a63be4f1c931819459b8f0","qcUserId":"68a63874fca958620f9e640e","inspectionDate":"2026-03-23T23:00:53.797Z","qcUserName":"Chance Hoffman","id":"69c1c6263172b763cbdc78e2","created_date":"2026-03-23T23:00:54.113000","updated_date":"2026-03-23T23:00:54.113000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c6105b135392f6a0cb1c'),'89da16ab-7475-419e-a9bb-5f9ca6a03e17','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','100','completed','Jon is an excellent technician. During my visit to his jobsite, I saw him arrive early, and immediately grab gear to begin prepping for his first install. His communication with the site has been thorough, and the site contact, Tony, has been very complimentary. Jon knows these installs very well, and his attitude is always positive. ','2026-03-23T23:00:32.047Z','2026-03-23T23:00:32.161000','2026-03-23T23:00:32.161000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T23:00:32.047Z','69c1c6105b135392f6a0cb1c','68a63a837ca58232bd528115','68a6388cc778ad7fe64526ca','{"score":"100","notes":"Jon is an excellent technician. During my visit to his jobsite, I saw him arrive early, and immediately grab gear to begin prepping for his first install. His communication with the site has been thorough, and the site contact, Tony, has been very complimentary. Jon knows these installs very well, and his attitude is always positive. ","technicianId":"68a63a837ca58232bd528115","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T23:00:32.047Z","qcUserName":"Ryan Miller","id":"69c1c6105b135392f6a0cb1c","created_date":"2026-03-23T23:00:32.161000","updated_date":"2026-03-23T23:00:32.161000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
