INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c5253998798349201ff7'),'cc239d20-e965-405b-8cf0-b75726fcf6c9','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','90','completed','Visited with Alec while he was working Summit Schools. Alec was on time or early for every shift. He is a good technician and understands the installs thoroughly at this point. I did note that when he is on delay, that he does not immediately try and find something else to do in the meantime, so I took the opportunity to coach him on the benefits of being proactive.','2026-03-23T22:56:37.661Z','2026-03-23T22:56:37.888000','2026-03-23T22:56:37.888000','c6eaf22e-8fbe-4d43-9aec-81928771d4ce','Ryan Miller','2026-03-23T22:56:37.661Z','69c1c5253998798349201ff7','68a630bf547db0192c9066b4','68a6388cc778ad7fe64526ca','{"score":"90","notes":"Visited with Alec while he was working Summit Schools. Alec was on time or early for every shift. He is a good technician and understands the installs thoroughly at this point. I did note that when he is on delay, that he does not immediately try and find something else to do in the meantime, so I took the opportunity to coach him on the benefits of being proactive.","technicianId":"68a630bf547db0192c9066b4","qcUserId":"68a6388cc778ad7fe64526ca","inspectionDate":"2026-03-23T22:56:37.661Z","qcUserName":"Ryan Miller","id":"69c1c5253998798349201ff7","created_date":"2026-03-23T22:56:37.888000","updated_date":"2026-03-23T22:56:37.888000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
