INSERT INTO public."QCInspection" (id,"technicianId","inspectorId",score,status,notes,inspection_date,created_at,updated_at,"qcUserId","qcUserName","inspectionDate",legacy_id,legacy_technician_id,legacy_qc_user_id,metadata,source_system) VALUES (public.m2_legacy_uuid('QCInspection:69c1c4912c47ceb68f04bfb4'),'a69f0a9c-fd70-4264-bf16-6391179fc29f','b599d2c9-da21-4dc4-b77f-77473fa8f75c','100','completed','Went to see James and Martin as well as John Withrow in Madisonville. James was not in the first day due to personal issues, but was on site the rest of the week after that and had no issues. We talked about proper communication with project team and the importance of keeping an open line of comms especially during delays. ','2026-03-23T22:54:09.765Z','2026-03-23T22:54:09.922000','2026-03-23T22:54:09.922000','b599d2c9-da21-4dc4-b77f-77473fa8f75c','Chance Hoffman','2026-03-23T22:54:09.765Z','69c1c4912c47ceb68f04bfb4','68a3e3a62793cf96ad29a899','68a63874fca958620f9e640e','{"score":"100","notes":"Went to see James and Martin as well as John Withrow in Madisonville. James was not in the first day due to personal issues, but was on site the rest of the week after that and had no issues. We talked about proper communication with project team and the importance of keeping an open line of comms especially during delays. ","technicianId":"68a3e3a62793cf96ad29a899","qcUserId":"68a63874fca958620f9e640e","inspectionDate":"2026-03-23T22:54:09.765Z","qcUserName":"Chance Hoffman","id":"69c1c4912c47ceb68f04bfb4","created_date":"2026-03-23T22:54:09.922000","updated_date":"2026-03-23T22:54:09.922000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
