INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:6a428b9bcf65a7daecad9a67'),'6457d94f-ba1c-4882-9939-991691035161','2026-06-29T15:13:31.057Z','Called him about a string of warranty returns that seem to have been an issue with sunbelt rushing out units and he said he had discussed the issue already with velociti. Then chatted a bit about his work situation. Says hes happy with work but took today off due to ac in his car being out and is hoping to have it back later today or tomorrow. Told him I would get with him in the near future to meet up in person.','2026-06-29T15:13:31.347000','Called him about a string of warranty returns that seem to have been an issue with sunbelt rushing out units and he said he had discussed the issue already with velociti. Then chatted a bit about his work situation. Says hes happy with work but took today off due to ac in his car being out and is hoping to have it back later today or tomorrow. Told him I would get with him in the near future to meet up in person.','choffman.contractor@m2fleetcom.com','mburkett.contractor@m2fleetcom.com','6a428b9bcf65a7daecad9a67','68a88f7b0722d741fc6f5bb4','{"note":"Called him about a string of warranty returns that seem to have been an issue with sunbelt rushing out units and he said he had discussed the issue already with velociti. Then chatted a bit about his work situation. Says hes happy with work but took today off due to ac in his car being out and is hoping to have it back later today or tomorrow. Told him I would get with him in the near future to meet up in person.","loggedBy":"choffman.contractor@m2fleetcom.com","technicianEmail":"mburkett.contractor@m2fleetcom.com","callDate":"2026-06-29T15:13:31.057Z","technicianId":"68a88f7b0722d741fc6f5bb4","id":"6a428b9bcf65a7daecad9a67","created_date":"2026-06-29T15:13:31.347000","updated_date":"2026-