INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:69d6ed83ab67b2e1a09cf871'),'0d2595b1-c405-4362-9b96-980221141db3','2026-04-09T00:06:27.858Z','Just called to see how things were going and let ask him to close out a few pending QC emails and reply all when doing so. He has been doing great with JR but they both are being made to do all the full installs as the other XPs on site are apparently not allowed to touch full installs. Not sure if theres a disconnect in the directive there somewhere but if not that could be an issue.','2026-04-09T00:06:27.979000','Just called to see how things were going and let ask him to close out a few pending QC emails and reply all when doing so. He has been doing great with JR but they both are being made to do all the full installs as the other XPs on site are apparently not allowed to touch full installs. Not sure if theres a disconnect in the directive there somewhere but if not that could be an issue.','choffman.contractor@m2fleetcom.com','rrodriguez.contractor@m2fleetcom.com','69d6ed83ab67b2e1a09cf871','68a63be4f1c931819459b8f0','{"note":"Just called to see how things were going and let ask him to close out a few pending QC emails and reply all when doing so. He has been doing great with JR but they both are being made to do all the full installs as the other XPs on site are apparently not allowed to touch full installs. Not sure if theres a disconnect in the directive there somewhere but if not that could be an issue.","loggedBy":"choffman.contractor@m2fleetcom.com","technicianEmail":"rrodriguez.contractor@m2fleetcom.com","callDate":"2026-04-09T00:06:27.858Z","technicianId":"68a63be4f1c931819459b8f0","id":"69d6ed83ab67b2e1a09cf871","created_date":"2026-04-09T00:06:27.979000","updated_date":"2026-04-09T00:06:27.979000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:69d6ecef2f2b382520348a1d'),'1f0fdc17-1969-48a8-8367-de25ad2a2cee','2026-04-09T00:03:58.959Z','Called to talk about going back through and closing out QC fails and to let me or Ryan know as he does as well as replying all to email chains. Other than that he has been doing a really good job. He mentioned other XPs on site not being allowed to do full installs leaving him and Rapha to do all the big installs while the other XPs do less work. Not sure thats fair for them to have to do that while also trying to keep site on deadline.','2026-04-09T00:03:59.168000','Called to talk about going back through and closing out QC fails and to let me or Ryan know as he does as well as replying all to email chains. Other than that he has been doing a really good job. He mentioned other XPs on site not being allowed to do full installs leaving him and Rapha to do all the big installs while the other XPs do less work. Not sure thats fair for them to have to do that while also trying to keep site on deadline.','choffman.contractor@m2fleetcom.com','ebaltazarjr.contractor@m2fleetcom.com','69d6ecef2f2b382520348a1d','68a6391a09e099d0f39fa327','{"note":"Called to talk about going back through and closing out QC fails and to let me or Ryan know as he does as well as replying all to email chains. Other than that he has been doing a really good job. He mentioned other XPs on site not being allowed to do full installs leaving him and Rapha to do all the big installs while the other XPs do less work. Not sure thats fair for them to have to do that while also trying to keep site on deadline.","loggedBy":"choffman.contractor@m2fleetcom.com","technicianEmail":"ebaltazarjr.contractor@m2fleetcom.com","callDate":"2026-04-09T00:03:58.959Z","technicianId":"68a6391a09e099d0f39fa327","id":"69d6ecef2f2b382520348a1d","created_date":"2026-04-09T00:03:59.168000","updated_date":"2026-04-09T00:03:59.168000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
