INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:6977d47c8d960f1f2c659a7e'),'ff93164e-8f6a-4754-8f21-7418f6820d0a','2026-01-26T20:54:20.108Z','Ty sounds like he is starting to get a little burned out at SBR in Colorado. He''s asked me a few times for a change of scenery, either a new contract or an SBR posting near his home. Ty has been a solid tech, but it sounds like he has been deceptive with Austin and Mike Levy at Velo to try and get himself closer to home, making it hard to sympathize with him.','2026-01-26T20:54:20.217000','Ty sounds like he is starting to get a little burned out at SBR in Colorado. He''s asked me a few times for a change of scenery, either a new contract or an SBR posting near his home. Ty has been a solid tech, but it sounds like he has been deceptive with Austin and Mike Levy at Velo to try and get himself closer to home, making it hard to sympathize with him.','rmiller.contractor@m2fleetcom.com','tcorley.contractor@m2fleetcom.com','6977d47c8d960f1f2c659a7e','68a7ddebea317d2ad16a61dd','{"note":"Ty sounds like he is starting to get a little burned out at SBR in Colorado. He''s asked me a few times for a change of scenery, either a new contract or an SBR posting near his home. Ty has been a solid tech, but it sounds like he has been deceptive with Austin and Mike Levy at Velo to try and get himself closer to home, making it hard to sympathize with him.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"tcorley.contractor@m2fleetcom.com","callDate":"2026-01-26T20:54:20.108Z","technicianId":"68a7ddebea317d2ad16a61dd","id":"6977d47c8d960f1f2c659a7e","created_date":"2026-01-26T20:54:20.217000","updated_date":"2026-01-26T20:54:20.217000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:6977d3ea5db4dd02da38006b'),'a1c3adb2-da49-4606-9314-ebed7503a27d','2026-01-26T20:51:54.509Z','Rodney says its business as usual up outside Seattle. He was able to come home for about a week for Christmas and spend some time with his family and friends and is back to work feeling refreshed. They were expecting some snow in his area over the weekend. Surprisingly, he says that Seattle doesn''t typically get much snow, and that, like Texas, the whole city will basically shut down with a light dusting. He said he has all the supplies he needs and is ready to shut-in for the weekend.','2026-01-26T20:51:54.596000','Rodney says its business as usual up outside Seattle. He was able to come home for about a week for Christmas and spend some time with his family and friends and is back to work feeling refreshed. They were expecting some snow in his area over the weekend. Surprisingly, he says that Seattle doesn''t typically get much snow, and that, like Texas, the whole city will basically shut down with a light dusting. He said he has all the supplies he needs and is ready to shut-in for the weekend.','rmiller.contractor@m2fleetcom.com','rhasty.contractor@m2fleetcom.com','6977d3ea5db4dd02da38006b','68a63c307ca58232bd5281c2','{"note":"Rodney says its business as usual up outside Seattle. He was able to come home for about a week for Christmas and spend some time with his family and friends and is back to work feeling refreshed. They were expecting some snow in his area over the weekend. Surprisingly, he says that Seattle doesn''t typically get much snow, and that, like Texas, the whole city will basically shut down with a light dusting. He said he has all the supplies he needs and is ready to shut-in for the weekend.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"rhasty.contractor@m2fleetcom.com","callDate":"2026-01-26T20:51:54.509Z","technicianId":"68a63c307ca58232bd5281c2","id":"6977d3ea5db4dd02da38006b","created_date":"2026-01-26T20:51:54.596000","updated_date":"2026-01-26T20:51:54.596000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:6977d2efcad1aa53178af642'),'0ea4bdb1-b8ec-4771-81a7-b1ba2e312dd7','2026-01-26T20:47:43.823Z','Ray is coasting on SBR. Availability in his area is still weak, but he has a good system worked out with his scheduler and doesn''t have to bounce around as much as some of our other techs. He was getting his house prepped and planning on staying inside and warm with his wife and baby.','2026-01-26T20:47:43.903000','Ray is coasting on SBR. Availability in his area is still weak, but he has a good system worked out with his scheduler and doesn''t have to bounce around as much as some of our other techs. He was getting his house prepped and planning on staying inside and warm with his wife and baby.','rmiller.contractor@m2fleetcom.com','rbustamante.contractor@m2fleetcom.com','6977d2efcad1aa53178af642','68a63bf16e5b61a47075febc','{"note":"Ray is coasting on SBR. Availability in his area is still weak, but he has a good system worked out with his scheduler and doesn''t have to bounce around as much as some of our other techs. He was getting his house prepped and planning on staying inside and warm with his wife and baby.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"rbustamante.contractor@m2fleetcom.com","callDate":"2026-01-26T20:47:43.823Z","technicianId":"68a63bf16e5b61a47075febc","id":"6977d2efcad1aa53178af642","created_date":"2026-01-26T20:47:43.903000","updated_date":"2026-01-26T20:47:43.903000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
