INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692d0de99c5bf13c146f9675'),'b6626079-c2d3-4fb1-bee9-d1685e1d2bc6','2025-12-01T03:39:21.607Z','No issues to report. Very happy with location and current contract. Wanted to know about his friend possibly getting hired.','2025-12-01T03:39:21.989000','No issues to report. Very happy with location and current contract. Wanted to know about his friend possibly getting hired.','choffman.contractor@m2fleetcom.com','lhogg.contractor@m2fleetcom.com','692d0de99c5bf13c146f9675','68c7093b6b6d21dad18edbbc','{"note":"No issues to report. Very happy with location and current contract. Wanted to know about his friend possibly getting hired.","loggedBy":"choffman.contractor@m2fleetcom.com","technicianEmail":"lhogg.contractor@m2fleetcom.com","callDate":"2025-12-01T03:39:21.607Z","technicianId":"68c7093b6b6d21dad18edbbc","id":"692d0de99c5bf13c146f9675","created_date":"2025-12-01T03:39:21.989000","updated_date":"2025-12-01T03:39:21.989000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b573564fc07910b041dbd'),'34f15e5a-e76f-462d-bf07-b8e1caf35f0a','2025-11-29T20:27:34.346Z','Anthony does not sound like he is enjoying Sunbelt. He says that he gets routed around too much, and his vehicle is constantly full. He bought a storage unit out of pocket to help alleviate this, but he says he rarely gets to stop there to pick up gear. He is driving a Jeep Gladiator, which is not an idea vehicle for a job like this. Furthermore, he tells me that hotels for the holiday week are all either booked full, or at least $150 where he is working, and he can''t afford to miss a week of work to come home for Thanksgiving either. Financially, he sounds like he is struggling. I don''t know if this particular contract is a bad fit for Anthony, or if it is the job overall, but I don''t see him being successful with SBR at the very least.','2025-11-29T20:27:33.799000','Anthony does not sound like he is enjoying Sunbelt. He says that he gets routed around too much, and his vehicle is constantly full. He bought a storage unit out of pocket to help alleviate this, but he says he rarely gets to stop there to pick up gear. He is driving a Jeep Gladiator, which is not an idea vehicle for a job like this. Furthermore, he tells me that hotels for the holiday week are all either booked full, or at least $150 where he is working, and he can''t afford to miss a week of work to come home for Thanksgiving either. Financially, he sounds like he is struggling. I don''t know if this particular contract is a bad fit for Anthony, or if it is the job overall, but I don''t see him being successful with SBR at the very least.','rmiller.contractor@m2fleetcom.com','aarsenault.contractor@m2fleetcom.com','692b573564fc07910b041dbd','68a630f9e2735459ce4ae6b4','{"note":"Anthony does not sound like he is enjoying Sunbelt. He says that he gets routed around too much, and his vehicle is constantly full. He bought a storage unit out of pocket to help alleviate this, but he says he rarely gets to stop there to pick up gear. He is driving a Jeep Gladiator, which is not an idea vehicle for a job like this. Furthermore, he tells me that hotels for the holiday week are all either booked full, or at least $150 where he is working, and he can''t afford to miss a week of work to come home for Thanksgiving either. Financially, he sounds like he is struggling. I don''t know if this particular contract is a bad fit for Anthony, or if it is the job overall, but I don''t see him being successful with SBR at the very least.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"aarsenault.contractor@m2fleetcom.com","callDate":"2025-11-29T20:27:34.346Z","technicianId":"68a630f9e2735459ce4ae6b4","id":"692b573564fc07910b041dbd","created_date":"2025-11-29T20:27:33.799000","updated_date":"2025-11-29T20:27:33.799000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b55bce8640cd61b6b9506'),'a9ce953c-5b16-4cf7-bcd2-8a81990bdf86','2025-11-29T20:21:16.852Z','Brianna is doing well on Sunbelt. She has been learning new services every week and says that Allen has been very patient and helpful. She likes the job, but had concerns about her pay rate. She has asked to be given a travel route so that she can earn more, as she has no real desire to be at home in Houston every night. She stated that if her safety is a factor in keeping her local, she is able to defend herself, and that the part of Houston that she lives in isn''t safe as it is.','2025-11-29T20:21:16.290000','Brianna is doing well on Sunbelt. She has been learning new services every week and says that Allen has been very patient and helpful. She likes the job, but had concerns about her pay rate. She has asked to be given a travel route so that she can earn more, as she has no real desire to be at home in Houston every night. She stated that if her safety is a factor in keeping her local, she is able to defend herself, and that the part of Houston that she lives in isn''t safe as it is.','rmiller.contractor@m2fleetcom.com','bmclaughlin.contractor@m2fleetcom.com','692b55bce8640cd61b6b9506','68a6311897418fb0fe1e5cf3','{"note":"Brianna is doing well on Sunbelt. She has been learning new services every week and says that Allen has been very patient and helpful. She likes the job, but had concerns about her pay rate. She has asked to be given a travel route so that she can earn more, as she has no real desire to be at home in Houston every night. She stated that if her safety is a factor in keeping her local, she is able to defend herself, and that the part of Houston that she lives in isn''t safe as it is.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"bmclaughlin.contractor@m2fleetcom.com","callDate":"2025-11-29T20:21:16.852Z","technicianId":"68a6311897418fb0fe1e5cf3","id":"692b55bce8640cd61b6b9506","created_date":"2025-11-29T20:21:16.290000","updated_date":"2025-11-29T20:21:16.290000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b5516c8f6aa1a17d8d710'),'0d2595b1-c405-4362-9b96-980221141db3','2025-11-29T20:18:31.088Z','Rafa sounded happy when we spoke. He was off for Thanksgiving and helping his brother smoke a turkey and a brisket. He has been dabbling in smoked meat for a few years now and says he always looks forward to big get-togethers so he can show off for his friends and family. He has been having a few technical issues on Lincare - all related to his iphone. Velociti had mentioned sending out Samsung tablets for techs with iphones, but Rafa got tired of waiting and went and bought a cheap Android so he could work properly again. He seems very dedicated to his work, and I hope we keep him for years to come.','2025-11-29T20:18:30.585000','Rafa sounded happy when we spoke. He was off for Thanksgiving and helping his brother smoke a turkey and a brisket. He has been dabbling in smoked meat for a few years now and says he always looks forward to big get-togethers so he can show off for his friends and family. He has been having a few technical issues on Lincare - all related to his iphone. Velociti had mentioned sending out Samsung tablets for techs with iphones, but Rafa got tired of waiting and went and bought a cheap Android so he could work properly again. He seems very dedicated to his work, and I hope we keep him for years to come.','rmiller.contractor@m2fleetcom.com','rrodriguez.contractor@m2fleetcom.com','692b5516c8f6aa1a17d8d710','68a63be4f1c931819459b8f0','{"note":"Rafa sounded happy when we spoke. He was off for Thanksgiving and helping his brother smoke a turkey and a brisket. He has been dabbling in smoked meat for a few years now and says he always looks forward to big get-togethers so he can show off for his friends and family. He has been having a few technical issues on Lincare - all related to his iphone. Velociti had mentioned sending out Samsung tablets for techs with iphones, but Rafa got tired of waiting and went and bought a cheap Android so he could work properly again. He seems very dedicated to his work, and I hope we keep him for years to come.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"rrodriguez.contractor@m2fleetcom.com","callDate":"2025-11-29T20:18:31.088Z","technicianId":"68a63be4f1c931819459b8f0","id":"692b5516c8f6aa1a17d8d710","created_date":"2025-11-29T20:18:30.585000","updated_date":"2025-11-29T20:18:30.585000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b544fbebeb4862d26e729'),'1f0fdc17-1969-48a8-8367-de25ad2a2cee','2025-11-29T20:15:11.579Z','This was an in person visit: Erik and I went up to Velociti for  a week of 360 training. Erik is a great tech that doesn''t ask a lot of dumb questions, pays attention to what he''s being shown, and is able to translate that to his own hands. He distinguished himself as a rock star early on in the training and was given lots of praise from the various trainers. Erik has a good attitude, and is able to roll with the punches when needed. He likes the job, and while he would prefer not to go back to Greco and Sons, he expects to stay with us for a long time. Erik Jr and his father are two of my favorite technicians, and am happy to have them both on our crew.','2025-11-29T20:15:11','This was an in person visit: Erik and I went up to Velociti for  a week of 360 training. Erik is a great tech that doesn''t ask a lot of dumb questions, pays attention to what he''s being shown, and is able to translate that to his own hands. He distinguished himself as a rock star early on in the training and was given lots of praise from the various trainers. Erik has a good attitude, and is able to roll with the punches when needed. He likes the job, and while he would prefer not to go back to Greco and Sons, he expects to stay with us for a long time. Erik Jr and his father are two of my favorite technicians, and am happy to have them both on our crew.','rmiller.contractor@m2fleetcom.com','ebaltazarjr.contractor@m2fleetcom.com','692b544fbebeb4862d26e729','68a6391a09e099d0f39fa327','{"note":"This was an in person visit: Erik and I went up to Velociti for  a week of 360 training. Erik is a great tech that doesn''t ask a lot of dumb questions, pays attention to what he''s being shown, and is able to translate that to his own hands. He distinguished himself as a rock star early on in the training and was given lots of praise from the various trainers. Erik has a good attitude, and is able to roll with the punches when needed. He likes the job, and while he would prefer not to go back to Greco and Sons, he expects to stay with us for a long time. Erik Jr and his father are two of my favorite technicians, and am happy to have them both on our crew.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"ebaltazarjr.contractor@m2fleetcom.com","callDate":"2025-11-29T20:15:11.579Z","technicianId":"68a6391a09e099d0f39fa327","id":"692b544fbebeb4862d26e729","created_date":"2025-11-29T20:15:11","updated_date":"2025-11-29T20:15:11","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b5337e8640cd61b6b9396'),'9a87bddd-2997-4b78-b075-9c939f84f423','2025-11-29T20:10:31.563Z','Karon has a fantastic attitude. He says he feels blessed every day to have this job, and compared to what he was doing before he came to us, he has no complaints whatsoever. He''s looking forward to a quiet weekend with no plans. He says he''s perfectly happy with his route, but would like to come back to Houston if there is any availability.','2025-11-29T20:10:31.008000','Karon has a fantastic attitude. He says he feels blessed every day to have this job, and compared to what he was doing before he came to us, he has no complaints whatsoever. He''s looking forward to a quiet weekend with no plans. He says he''s perfectly happy with his route, but would like to come back to Houston if there is any availability.','rmiller.contractor@m2fleetcom.com','ksmith.contractor@m2fleetcom.com','692b5337e8640cd61b6b9396','68a63af61d8018e91bdaf548','{"note":"Karon has a fantastic attitude. He says he feels blessed every day to have this job, and compared to what he was doing before he came to us, he has no complaints whatsoever. He''s looking forward to a quiet weekend with no plans. He says he''s perfectly happy with his route, but would like to come back to Houston if there is any availability.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"ksmith.contractor@m2fleetcom.com","callDate":"2025-11-29T20:10:31.563Z","technicianId":"68a63af61d8018e91bdaf548","id":"692b5337e8640cd61b6b9396","created_date":"2025-11-29T20:10:31.008000","updated_date":"2025-11-29T20:10:31.008000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b520e92537e358d13894d'),'0398a6ec-bdaf-4d84-8d7b-1a8083b967c8','2025-11-29T20:05:35.181Z','Maci is happy to be home for Thanksgiving. They don''t have any big plans, just a couple of people over. She still enjoys the job, and doesn''t mind the travel, but we will probably lose her when their grandchild is born so that she can help take care of the baby. She asked about Harvey, and I let her and Justin both know that he was ok and recovering.','2025-11-29T20:05:34.703000','Maci is happy to be home for Thanksgiving. They don''t have any big plans, just a couple of people over. She still enjoys the job, and doesn''t mind the travel, but we will probably lose her when their grandchild is born so that she can help take care of the baby. She asked about Harvey, and I let her and Justin both know that he was ok and recovering.','rmiller.contractor@m2fleetcom.com','mwhite.contractor@m2fleetcom.com','692b520e92537e358d13894d','68a63b3ff726c828cc63d894','{"note":"Maci is happy to be home for Thanksgiving. They don''t have any big plans, just a couple of people over. She still enjoys the job, and doesn''t mind the travel, but we will probably lose her when their grandchild is born so that she can help take care of the baby. She asked about Harvey, and I let her and Justin both know that he was ok and recovering.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"mwhite.contractor@m2fleetcom.com","callDate":"2025-11-29T20:05:35.181Z","technicianId":"68a63b3ff726c828cc63d894","id":"692b520e92537e358d13894d","created_date":"2025-11-29T20:05:34.703000","updated_date":"2025-11-29T20:05:34.703000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b511ed54995cb087e7513'),'89da16ab-7475-419e-a9bb-5f9ca6a03e17','2025-11-29T20:01:35.432Z','As expected, Amazon was a breeze for Jonny. His attitude is excellent, he adapts very well to every install we put him on, and is able to effectively communicate any issues. He likes the work we do and wants to stay with us as long as we will have him. I would tap him for more responsibility if and when the need arises. He is easily one of our best technicians.','2025-11-29T20:01:34.871000','As expected, Amazon was a breeze for Jonny. His attitude is excellent, he adapts very well to every install we put him on, and is able to effectively communicate any issues. He likes the work we do and wants to stay with us as long as we will have him. I would tap him for more responsibility if and when the need arises. He is easily one of our best technicians.','rmiller.contractor@m2fleetcom.com','jmaize.contractor@m2fleetcom.com','692b511ed54995cb087e7513','68a63a837ca58232bd528115','{"note":"As expected, Amazon was a breeze for Jonny. His attitude is excellent, he adapts very well to every install we put him on, and is able to effectively communicate any issues. He likes the work we do and wants to stay with us as long as we will have him. I would tap him for more responsibility if and when the need arises. He is easily one of our best technicians.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"jmaize.contractor@m2fleetcom.com","callDate":"2025-11-29T20:01:35.432Z","technicianId":"68a63a837ca58232bd528115","id":"692b511ed54995cb087e7513","created_date":"2025-11-29T20:01:34.871000","updated_date":"2025-11-29T20:01:34.871000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b50706c28c74ada6958c2'),'4a42b659-91c3-49ce-9b6d-14cbea1eb8bc','2025-11-29T19:58:40.762Z','Rance has been doing better on Davey Tree. The installs are a lot more straightforward than Amazon, and because he needs less support, he is able to get away with a little less communication. This is still his weak point, and he will need to improve his communication skills if he wants to be successful here in the long term. His responses, while complete, are usually very delayed from when you ask him, in particular. I want to see Rance improve, because I see a guy with a solid foundation that takes pride in his own work. I will continue to coach.','2025-11-29T19:58:40.211000','Rance has been doing better on Davey Tree. The installs are a lot more straightforward than Amazon, and because he needs less support, he is able to get away with a little less communication. This is still his weak point, and he will need to improve his communication skills if he wants to be successful here in the long term. His responses, while complete, are usually very delayed from when you ask him, in particular. I want to see Rance improve, because I see a guy with a solid foundation that takes pride in his own work. I will continue to coach.','rmiller.contractor@m2fleetcom.com','ramiller.contractor@m2fleetcom.com','692b50706c28c74ada6958c2','68a63bd2ccc87b9523363bc6','{"note":"Rance has been doing better on Davey Tree. The installs are a lot more straightforward than Amazon, and because he needs less support, he is able to get away with a little less communication. This is still his weak point, and he will need to improve his communication skills if he wants to be successful here in the long term. His responses, while complete, are usually very delayed from when you ask him, in particular. I want to see Rance improve, because I see a guy with a solid foundation that takes pride in his own work. I will continue to coach.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"ramiller.contractor@m2fleetcom.com","callDate":"2025-11-29T19:58:40.762Z","technicianId":"68a63bd2ccc87b9523363bc6","id":"692b50706c28c74ada6958c2","created_date":"2025-11-29T19:58:40.211000","updated_date":"2025-11-29T19:58:40.211000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b4f850983259b3875e487'),'25b22ea9-9fea-49be-8227-689e1f50faa8','2025-11-29T19:54:46.350Z','Paul was headed home for Thanksgiving when I talked to him. He''s ready for a couple days of quiet time with his wife and his cats. He said the new axle came for his trailer, but it was defective on arrival, so he is still immobile. The new part should be arriving early the week after Thanksgiving and he will get the axle swapped as soon as he gets back from Tyler.','2025-11-29T19:54:45.771000','Paul was headed home for Thanksgiving when I talked to him. He''s ready for a couple days of quiet time with his wife and his cats. He said the new axle came for his trailer, but it was defective on arrival, so he is still immobile. The new part should be arriving early the week after Thanksgiving and he will get the axle swapped as soon as he gets back from Tyler.','rmiller.contractor@m2fleetcom.com','ppavilionis.contractor@m2fleetcom.com','692b4f850983259b3875e487','68a63bc78f545166ef42199a','{"note":"Paul was headed home for Thanksgiving when I talked to him. He''s ready for a couple days of quiet time with his wife and his cats. He said the new axle came for his trailer, but it was defective on arrival, so he is still immobile. The new part should be arriving early the week after Thanksgiving and he will get the axle swapped as soon as he gets back from Tyler.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"ppavilionis.contractor@m2fleetcom.com","callDate":"2025-11-29T19:54:46.350Z","technicianId":"68a63bc78f545166ef42199a","id":"692b4f850983259b3875e487","created_date":"2025-11-29T19:54:45.771000","updated_date":"2025-11-29T19:54:45.771000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b4ef3c059466356e7136e'),'18c1b601-f6f8-4bda-9a3b-d449dbce1eba','2025-11-29T19:52:19.695Z','Mike was a little under the weather when we talked. He has been getting frequent migraines lately. He and his wife didn''t feel like cooking for Thanksgiving, so they ordered steak from Texas de Brazil. Before Mike had a chance to eat his steak, his Great Pyrenees ate the whole thing. Sounds like he''s cooking a ham this weekend as consolation. Despite all of this, he says he is still happy on Amazon. His schedulers do a pretty good job of not running him all over town, and he has his routine set that he''s able to get finished up long before 5am nightly.','2025-11-29T19:52:19.202000','Mike was a little under the weather when we talked. He has been getting frequent migraines lately. He and his wife didn''t feel like cooking for Thanksgiving, so they ordered steak from Texas de Brazil. Before Mike had a chance to eat his steak, his Great Pyrenees ate the whole thing. Sounds like he''s cooking a ham this weekend as consolation. Despite all of this, he says he is still happy on Amazon. His schedulers do a pretty good job of not running him all over town, and he has his routine set that he''s able to get finished up long before 5am nightly.','rmiller.contractor@m2fleetcom.com','mpreacher.contractor@m2fleetcom.com','692b4ef3c059466356e7136e','68a63b9bef1ecb55a29372a6','{"note":"Mike was a little under the weather when we talked. He has been getting frequent migraines lately. He and his wife didn''t feel like cooking for Thanksgiving, so they ordered steak from Texas de Brazil. Before Mike had a chance to eat his steak, his Great Pyrenees ate the whole thing. Sounds like he''s cooking a ham this weekend as consolation. Despite all of this, he says he is still happy on Amazon. His schedulers do a pretty good job of not running him all over town, and he has his routine set that he''s able to get finished up long before 5am nightly.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"mpreacher.contractor@m2fleetcom.com","callDate":"2025-11-29T19:52:19.695Z","technicianId":"68a63b9bef1ecb55a29372a6","id":"692b4ef3c059466356e7136e","created_date":"2025-11-29T19:52:19.202000","updated_date":"2025-11-29T19:52:19.202000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b4d7e40b1adfa132d4fd6'),'e692e22e-d778-4180-ba56-cf6bc9b932fc','2025-11-29T19:46:07.143Z','Micah sounded in good spirits. He''s home for Thanksgiving week and just happy to be at home with his family for a minute. He said Amazon has been going well, and is much happier now that he isn''t working for Donna.','2025-11-29T19:46:06.545000','Micah sounded in good spirits. He''s home for Thanksgiving week and just happy to be at home with his family for a minute. He said Amazon has been going well, and is much happier now that he isn''t working for Donna.','rmiller.contractor@m2fleetcom.com','mlinville.contractor@m2fleetcom.com','692b4d7e40b1adfa132d4fd6','68a63b8109e099d0f39fa3e3','{"note":"Micah sounded in good spirits. He''s home for Thanksgiving week and just happy to be at home with his family for a minute. He said Amazon has been going well, and is much happier now that he isn''t working for Donna.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"mlinville.contractor@m2fleetcom.com","callDate":"2025-11-29T19:46:07.143Z","technicianId":"68a63b8109e099d0f39fa3e3","id":"692b4d7e40b1adfa132d4fd6","created_date":"2025-11-29T19:46:06.545000","updated_date":"2025-11-29T19:46:06.545000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b4bdde2bd4a699c9415a0'),'11bd3b49-c31b-47ae-8a43-d3f414b9777c','2025-11-29T19:39:09.841Z','Henry is doing well on Amazon. He has the job down to a routine and rarely has to work a long night. He says the night time support team have been very helpful, and his schedulers have been doing a pretty good job. He mentioned that he spends most of his time in Virginia, and, while he isn''t dissatisfied with the job, if anything opens up in North Carolina, he would be interested.','2025-11-29T19:39:09.328000','Henry is doing well on Amazon. He has the job down to a routine and rarely has to work a long night. He says the night time support team have been very helpful, and his schedulers have been doing a pretty good job. He mentioned that he spends most of his time in Virginia, and, while he isn''t dissatisfied with the job, if anything opens up in North Carolina, he would be interested.','rmiller.contractor@m2fleetcom.com','hfernandez.contractor@m2fleetcom.com','692b4bdde2bd4a699c9415a0','68a639d3f267eea008ccb1d8','{"note":"Henry is doing well on Amazon. He has the job down to a routine and rarely has to work a long night. He says the night time support team have been very helpful, and his schedulers have been doing a pretty good job. He mentioned that he spends most of his time in Virginia, and, while he isn''t dissatisfied with the job, if anything opens up in North Carolina, he would be interested.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"hfernandez.contractor@m2fleetcom.com","callDate":"2025-11-29T19:39:09.841Z","technicianId":"68a639d3f267eea008ccb1d8","id":"692b4bdde2bd4a699c9415a0","created_date":"2025-11-29T19:39:09.328000","updated_date":"2025-11-29T19:39:09.328000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b4a53e8640cd61b6b8623'),'79a2f92c-2fcb-4513-bea9-dd330470cb3c','2025-11-29T19:32:36.072Z','Victor is back at 100% and having a good time with the job. He says the money has allowed him to pay off his debt and now he is working on building his future with his wife. He said he just bought a small grill and has been grocery shopping and cooking out on the road to help him eat better, and as an aside, he has been saving more money. Victor''s attitude is always positive, and he puts a lot of pride into his work. He is a great asset to our crew.','2025-11-29T19:32:35.558000','Victor is back at 100% and having a good time with the job. He says the money has allowed him to pay off his debt and now he is working on building his future with his wife. He said he just bought a small grill and has been grocery shopping and cooking out on the road to help him eat better, and as an aside, he has been saving more money. Victor''s attitude is always positive, and he puts a lot of pride into his work. He is a great asset to our crew.','rmiller.contractor@m2fleetcom.com','vmendoza.contractor@m2fleetcom.com','692b4a53e8640cd61b6b8623','68a901f089d2da1c8599b94f','{"note":"Victor is back at 100% and having a good time with the job. He says the money has allowed him to pay off his debt and now he is working on building his future with his wife. He said he just bought a small grill and has been grocery shopping and cooking out on the road to help him eat better, and as an aside, he has been saving more money. Victor''s attitude is always positive, and he puts a lot of pride into his work. He is a great asset to our crew.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"vmendoza.contractor@m2fleetcom.com","callDate":"2025-11-29T19:32:36.072Z","technicianId":"68a901f089d2da1c8599b94f","id":"692b4a53e8640cd61b6b8623","created_date":"2025-11-29T19:32:35.558000","updated_date":"2025-11-29T19:32:35.558000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b496283506cbf3a3bc260'),'2a106d6a-8ea6-4893-9d99-bf74173317cd','2025-11-29T19:28:35.216Z','This was an in-person visit: Weldon is a solid tech. He is adapting well to the requirements of the Amazon Victorinox project and doing a good job of communicating with his project team. Weldon is proactive about searching for alternate keys when his primary assets are unavailable, and doesn''t waste time in between services. He presents well and I really like his attitude. He''s a gearhead and builds quarter mile cars with his buddies when he isn''t working for us. He sounds like he really likes the job and says he is in it for the long haul.','2025-11-29T19:28:34.731000','This was an in-person visit: Weldon is a solid tech. He is adapting well to the requirements of the Amazon Victorinox project and doing a good job of communicating with his project team. Weldon is proactive about searching for alternate keys when his primary assets are unavailable, and doesn''t waste time in between services. He presents well and I really like his attitude. He''s a gearhead and builds quarter mile cars with his buddies when he isn''t working for us. He sounds like he really likes the job and says he is in it for the long haul.','rmiller.contractor@m2fleetcom.com','warmstrong.contractor@m2fleetcom.com','692b496283506cbf3a3bc260','68d82981f2966374778bba44','{"note":"This was an in-person visit: Weldon is a solid tech. He is adapting well to the requirements of the Amazon Victorinox project and doing a good job of communicating with his project team. Weldon is proactive about searching for alternate keys when his primary assets are unavailable, and doesn''t waste time in between services. He presents well and I really like his attitude. He''s a gearhead and builds quarter mile cars with his buddies when he isn''t working for us. He sounds like he really likes the job and says he is in it for the long haul.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"warmstrong.contractor@m2fleetcom.com","callDate":"2025-11-29T19:28:35.216Z","technicianId":"68d82981f2966374778bba44","id":"692b496283506cbf3a3bc260","created_date":"2025-11-29T19:28:34.731000","updated_date":"2025-11-29T19:28:34.731000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b3fb440b1adfa132d4406'),'48031fcb-4330-4f92-90bc-df9550b14979','2025-11-29T18:47:17.233Z','Doing well. He and Maci are home for Thanksgiving. Emerald has been going well. The installs are super easy, and he "has Connor wrapped around his finger" so they get a lot of support with whatever they need. He doesn''t really care for Amazon''s overnight shift and mentioned he''d be interested if something with an earlier start time came up.','2025-11-29T18:47:16.622000','Doing well. He and Maci are home for Thanksgiving. Emerald has been going well. The installs are super easy, and he "has Connor wrapped around his finger" so they get a lot of support with whatever they need. He doesn''t really care for Amazon''s overnight shift and mentioned he''d be interested if something with an earlier start time came up.','rmiller.contractor@m2fleetcom.com','jmclean.contractor@m2fleetcom.com','692b3fb440b1adfa132d4406','68a4fbc94354850115e95a02','{"note":"Doing well. He and Maci are home for Thanksgiving. Emerald has been going well. The installs are super easy, and he \"has Connor wrapped around his finger\" so they get a lot of support with whatever they need. He doesn''t really care for Amazon''s overnight shift and mentioned he''d be interested if something with an earlier start time came up.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"jmclean.contractor@m2fleetcom.com","callDate":"2025-11-29T18:47:17.233Z","technicianId":"68a4fbc94354850115e95a02","id":"692b3fb440b1adfa132d4406","created_date":"2025-11-29T18:47:16.622000","updated_date":"2025-11-29T18:47:16.622000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692b3dfed54995cb087e686a'),'cc239d20-e965-405b-8cf0-b75726fcf6c9','2025-11-29T18:39:58.904Z','Alec has been having an easy time on Davey Tree. The installs are fairly simple and he''s been able to get everything done and get home well before midnight. He loves his old 454 Suburban, but it has been killing him on fuel costs. He has been tapped for the Summit School project coming up, and is ready for the change of pace and steady work. I think he will make a good fit for the Summit team.','2025-11-29T18:39:58.399000','Alec has been having an easy time on Davey Tree. The installs are fairly simple and he''s been able to get everything done and get home well before midnight. He loves his old 454 Suburban, but it has been killing him on fuel costs. He has been tapped for the Summit School project coming up, and is ready for the change of pace and steady work. I think he will make a good fit for the Summit team.','rmiller.contractor@m2fleetcom.com','agray.contractor@m2fleetcom.com','692b3dfed54995cb087e686a','68a630bf547db0192c9066b4','{"note":"Alec has been having an easy time on Davey Tree. The installs are fairly simple and he''s been able to get everything done and get home well before midnight. He loves his old 454 Suburban, but it has been killing him on fuel costs. He has been tapped for the Summit School project coming up, and is ready for the change of pace and steady work. I think he will make a good fit for the Summit team.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"agray.contractor@m2fleetcom.com","callDate":"2025-11-29T18:39:58.904Z","technicianId":"68a630bf547db0192c9066b4","id":"692b3dfed54995cb087e686a","created_date":"2025-11-29T18:39:58.399000","updated_date":"2025-11-29T18:39:58.399000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
