INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:692735af8069282fae5eef94'),'6e3fac53-60f2-46aa-a940-3c02aa6075e8','2025-11-26T17:15:27.060Z','Talked with Josh this morning he is at home this week for Thanksgiving. Looking forward to starting TU700''S as he thinks it will add more work for him. Travels Greenville to Columbia then stays for a day or 2 then down to Georgia for a day or two then back to Greenville. Traveling about 500 miles a week. Doesnt konw from day to day where he will be wont find out until 2 o''clock wehre he will be the next day.  He seems to be doing great otherwise and is enjoying be home with the family for Thanksgiving.','2025-11-26T17:15:27.284000','Talked with Josh this morning he is at home this week for Thanksgiving. Looking forward to starting TU700''S as he thinks it will add more work for him. Travels Greenville to Columbia then stays for a day or 2 then down to Georgia for a day or two then back to Greenville. Traveling about 500 miles a week. Doesnt konw from day to day where he will be wont find out until 2 o''clock wehre he will be the next day.  He seems to be doing great otherwise and is enjoying be home with the family for Thanksgiving.','austin@m2fleetcom.com','jknisley.contractor@m2fleetcom.com','692735af8069282fae5eef94','68c7094544fac58987afaf06','{"note":"Talked with Josh this morning he is at home this week for Thanksgiving. Looking forward to starting TU700''S as he thinks it will add more work for him. Travels Greenville to Columbia then stays for a day or 2 then down to Georgia for a day or two then back to Greenville. Traveling about 500 miles a week. Doesnt konw from day to day where he will be wont find out until 2 o''clock wehre he will be the next day.  He seems to be doing great otherwise and is enjoying be home with the family for Thanksgiving.","loggedBy":"austin@m2fleetcom.com","technicianEmail":"jknisley.contractor@m2fleetcom.com","callDate":"2025-11-26T17:15:27.060Z","technicianId":"68c7094544fac58987afaf06","id":"692735af8069282fae5eef94","created_date":"2025-11-26T17:15:27.284000","updated_date":"2025-11-26T17:15:27.284000","created_by_id":"68a390239868be00767c8ae9","created_by":"austin@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:69272d32cc03a262b3aa2ff1'),'34f15e5a-e76f-462d-bf07-b8e1caf35f0a','2025-11-26T16:39:14.348Z','Talked to Anthony this morning, He said things are a little rough at the moment the structure on SunBelt especially around the Holidays as he had had his family come up for Thanksgiving and He is in a bad area and trying to find them Hotels. He is also saying that he is pulling Money out of Savings because he is not makeing enough and not being able to cook at hotels. He also broke some of his tools and had to replace them. He is just Frustrated. Not wanting to leave or give up on it.','2025-11-26T16:39:14.547000','Talked to Anthony this morning, He said things are a little rough at the moment the structure on SunBelt especially around the Holidays as he had had his family come up for Thanksgiving and He is in a bad area and trying to find them Hotels. He is also saying that he is pulling Money out of Savings because he is not makeing enough and not being able to cook at hotels. He also broke some of his tools and had to replace them. He is just Frustrated. Not wanting to leave or give up on it.','austin@m2fleetcom.com','aarsenault.contractor@m2fleetcom.com','69272d32cc03a262b3aa2ff1','68a630f9e2735459ce4ae6b4','{"note":"Talked to Anthony this morning, He said things are a little rough at the moment the structure on SunBelt especially around the Holidays as he had had his family come up for Thanksgiving and He is in a bad area and trying to find them Hotels. He is also saying that he is pulling Money out of Savings because he is not makeing enough and not being able to cook at hotels. He also broke some of his tools and had to replace them. He is just Frustrated. Not wanting to leave or give up on it.","loggedBy":"austin@m2fleetcom.com","technicianEmail":"aarsenault.contractor@m2fleetcom.com","callDate":"2025-11-26T16:39:14.348Z","technicianId":"68a630f9e2735459ce4ae6b4","id":"69272d32cc03a262b3aa2ff1","created_date":"2025-11-26T16:39:14.547000","updated_date":"2025-11-26T16:39:14.547000","created_by_id":"68a390239868be00767c8ae9","created_by":"austin@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
