INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68ed172fdd85ced66ba097df'),'361e055a-2bcb-42f8-b9be-d308dbdd9cc6','2025-10-13T15:13:50.743Z','Notes update Kam is moving to Houston towards the end of the year. I am currently working on getting him a local job out there','2025-10-13T15:13:51.922000','Notes update Kam is moving to Houston towards the end of the year. I am currently working on getting him a local job out there','austin@m2fleetcom.com','kmartineau.contractor@m2fleetcom.com','68ed172fdd85ced66ba097df','68a63ae9cb05041249de338e','{"note":"Notes update Kam is moving to Houston towards the end of the year. I am currently working on getting him a local job out there","loggedBy":"austin@m2fleetcom.com","technicianEmail":"kmartineau.contractor@m2fleetcom.com","callDate":"2025-10-13T15:13:50.743Z","technicianId":"68a63ae9cb05041249de338e","id":"68ed172fdd85ced66ba097df","created_date":"2025-10-13T15:13:51.922000","updated_date":"2025-10-13T15:13:51.922000","created_by_id":"68a390239868be00767c8ae9","created_by":"austin@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68ed1662c20cfbaecb40a365'),'453fa56b-01c0-4457-be94-fe89bcd95e74','2025-10-13T15:10:25.197Z','John Tran was doing well when we spoke. He was in a good mood, and said the Cottontail training had been going very well. The installs are simple, and the pace of work is easily managed. He doesn''t sound like he is enjoying or adjusting to the 8pm-5am production window, though. He indicated that he would probably be requesting a daytime job as soon as possible, and that he had already started talking to Austin to that extent.','2025-10-13T15:10:26.252000','John Tran was doing well when we spoke. He was in a good mood, and said the Cottontail training had been going very well. The installs are simple, and the pace of work is easily managed. He doesn''t sound like he is enjoying or adjusting to the 8pm-5am production window, though. He indicated that he would probably be requesting a daytime job as soon as possible, and that he had already started talking to Austin to that extent.','rmiller.contractor@m2fleetcom.com','jtran.contractor@m2fleetcom.com','68ed1662c20cfbaecb40a365','68a63a68217a039a0fc96c61','{"note":"John Tran was doing well when we spoke. He was in a good mood, and said the Cottontail training had been going very well. The installs are simple, and the pace of work is easily managed. He doesn''t sound like he is enjoying or adjusting to the 8pm-5am production window, though. He indicated that he would probably be requesting a daytime job as soon as possible, and that he had already started talking to Austin to that extent.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"jtran.contractor@m2fleetcom.com","callDate":"2025-10-13T15:10:25.197Z","technicianId":"68a63a68217a039a0fc96c61","id":"68ed1662c20cfbaecb40a365","created_date":"2025-10-13T15:10:26.252000","updated_date":"2025-10-13T15:10:26.252000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68ed15c58ba0a9ccfbc2e55d'),'7b66a0c4-6b8d-4ee4-ab0c-f36ce0e31504','2025-10-13T15:07:48.724Z','Jesse was as happy as ever. He says cottontail is very simple, and going well. He is a little concerned about his ability to keep up once they hit their own routes, but with the simplicity of the install, I think Jesse will be fine. Sounds like Beerfest has been going on while they were in Colorado training, which has made car rental a pain for him. He has been riding with Paul, and the two are getting along great. He says that John Tran is a good tech and a pretty friendly guy, and did not share Paul''s complaints.','2025-10-13T15:07:49.124000','Jesse was as happy as ever. He says cottontail is very simple, and going well. He is a little concerned about his ability to keep up once they hit their own routes, but with the simplicity of the install, I think Jesse will be fine. Sounds like Beerfest has been going on while they were in Colorado training, which has made car rental a pain for him. He has been riding with Paul, and the two are getting along great. He says that John Tran is a good tech and a pretty friendly guy, and did not share Paul''s complaints.','rmiller.contractor@m2fleetcom.com','jgonzalez.contractor@m2fleetcom.com','68ed15c58ba0a9ccfbc2e55d','68a63a3af1c931819459b886','{"note":"Jesse was as happy as ever. He says cottontail is very simple, and going well. He is a little concerned about his ability to keep up once they hit their own routes, but with the simplicity of the install, I think Jesse will be fine. Sounds like Beerfest has been going on while they were in Colorado training, which has made car rental a pain for him. He has been riding with Paul, and the two are getting along great. He says that John Tran is a good tech and a pretty friendly guy, and did not share Paul''s complaints.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"jgonzalez.contractor@m2fleetcom.com","callDate":"2025-10-13T15:07:48.724Z","technicianId":"68a63a3af1c931819459b886","id":"68ed15c58ba0a9ccfbc2e55d","created_date":"2025-10-13T15:07:49.124000","updated_date":"2025-10-13T15:07:49.124000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68ed153762e89a2f85d61bf0'),'361e055a-2bcb-42f8-b9be-d308dbdd9cc6','2025-10-13T15:05:25.595Z','Called Kam today he is not happy about haveing to travel so much on a local contract. His biggest Complaint is that they have him criss crossing with techs that live in the areas that he works and having those techs tracel to where he lives. Will continue up with Kam.','2025-10-13T15:05:27.486000','Called Kam today he is not happy about haveing to travel so much on a local contract. His biggest Complaint is that they have him criss crossing with techs that live in the areas that he works and having those techs tracel to where he lives. Will continue up with Kam.','austin@m2fleetcom.com','kmartineau.contractor@m2fleetcom.com','68ed153762e89a2f85d61bf0','68a63ae9cb05041249de338e','{"note":"Called Kam today he is not happy about haveing to travel so much on a local contract. His biggest Complaint is that they have him criss crossing with techs that live in the areas that he works and having those techs tracel to where he lives. Will continue up with Kam.","loggedBy":"austin@m2fleetcom.com","technicianEmail":"kmartineau.contractor@m2fleetcom.com","callDate":"2025-10-13T15:05:25.595Z","technicianId":"68a63ae9cb05041249de338e","id":"68ed153762e89a2f85d61bf0","created_date":"2025-10-13T15:05:27.486000","updated_date":"2025-10-13T15:05:27.486000","created_by_id":"68a390239868be00767c8ae9","created_by":"austin@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
