INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68ed13b9f4df325ffbb481c2'),'bbaeba8c-12a7-41a7-83ab-4fe0b5c28a9b','2025-10-13T14:59:03.861Z','Spoke with Joe today. Manny is on site with him today just to check on him on his way to Corpus. Seems to be doing just fine, says he has no complaints','2025-10-13T14:59:05.304000','Spoke with Joe today. Manny is on site with him today just to check on him on his way to Corpus. Seems to be doing just fine, says he has no complaints','austin@m2fleetcom.com','jmedina.contractor@m2fleetcom.com','68ed13b9f4df325ffbb481c2','68a63a4886133e51a2af911e','{"note":"Spoke with Joe today. Manny is on site with him today just to check on him on his way to Corpus. Seems to be doing just fine, says he has no complaints","loggedBy":"austin@m2fleetcom.com","technicianEmail":"jmedina.contractor@m2fleetcom.com","callDate":"2025-10-13T14:59:03.861Z","technicianId":"68a63a4886133e51a2af911e","id":"68ed13b9f4df325ffbb481c2","created_date":"2025-10-13T14:59:05.304000","updated_date":"2025-10-13T14:59:05.304000","created_by_id":"68a390239868be00767c8ae9","created_by":"austin@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68ed1151cfb438e543afd5da'),'25b22ea9-9fea-49be-8227-689e1f50faa8','2025-10-13T14:48:48.329Z','Paul was in good spirits when we spoke. Cottontail training went very well. Installs are very easy. Simple tablet charging cradle with an external aux battery. He says he has no issues working nights. Paul is getting along well with Jesse, but feels that John Tran isn''t much of a team player. Sounds like John leaves as soon as his install work is done for the night, rather than staying to help slower techs. They will be totally split up for their respective routes, so this is a non-issue.','2025-10-13T14:48:49.164000','Paul was in good spirits when we spoke. Cottontail training went very well. Installs are very easy. Simple tablet charging cradle with an external aux battery. He says he has no issues working nights. Paul is getting along well with Jesse, but feels that John Tran isn''t much of a team player. Sounds like John leaves as soon as his install work is done for the night, rather than staying to help slower techs. They will be totally split up for their respective routes, so this is a non-issue.','rmiller.contractor@m2fleetcom.com','ppavilionis.contractor@m2fleetcom.com','68ed1151cfb438e543afd5da','68a63bc78f545166ef42199a','{"note":"Paul was in good spirits when we spoke. Cottontail training went very well. Installs are very easy. Simple tablet charging cradle with an external aux battery. He says he has no issues working nights. Paul is getting along well with Jesse, but feels that John Tran isn''t much of a team player. Sounds like John leaves as soon as his install work is done for the night, rather than staying to help slower techs. They will be totally split up for their respective routes, so this is a non-issue.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"ppavilionis.contractor@m2fleetcom.com","callDate":"2025-10-13T14:48:48.329Z","technicianId":"68a63bc78f545166ef42199a","id":"68ed1151cfb438e543afd5da","created_date":"2025-10-13T14:48:49.164000","updated_date":"2025-10-13T14:48:49.164000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68ed1037c89cfac209f04048'),'0398a6ec-bdaf-4d84-8d7b-1a8083b967c8','2025-10-13T14:44:06.330Z','Maci sounded happy when we talked. The geotab installs were simple and straightforward, and the PM team was very easy to work with. Justin has his truck back, so shes finally been able to replace her old Nitro with the Caddy, which she loves. She is super excited about their first grandchild, but sounded a little nervous about helping raise it.','2025-10-13T14:44:07.329000','Maci sounded happy when we talked. The geotab installs were simple and straightforward, and the PM team was very easy to work with. Justin has his truck back, so shes finally been able to replace her old Nitro with the Caddy, which she loves. She is super excited about their first grandchild, but sounded a little nervous about helping raise it.','rmiller.contractor@m2fleetcom.com','mwhite.contractor@m2fleetcom.com','68ed1037c89cfac209f04048','68a63b3ff726c828cc63d894','{"note":"Maci sounded happy when we talked. The geotab installs were simple and straightforward, and the PM team was very easy to work with. Justin has his truck back, so shes finally been able to replace her old Nitro with the Caddy, which she loves. She is super excited about their first grandchild, but sounded a little nervous about helping raise it.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"mwhite.contractor@m2fleetcom.com","callDate":"2025-10-13T14:44:06.330Z","technicianId":"68a63b3ff726c828cc63d894","id":"68ed1037c89cfac209f04048","created_date":"2025-10-13T14:44:07.329000","updated_date":"2025-10-13T14:44:07.329000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68ed0e45a9b8b46e7c0def6e'),'48031fcb-4330-4f92-90bc-df9550b14979','2025-10-13T14:35:49.145Z','Justin seems to be doing ok for now. Money is still tight, but he says he is content. It sounds like Justin is planning to stick around for awhile longer, after all. He just got a new barrel for his .300 Norma and spent last weekend shooting it, with fantastic results.','2025-10-13T14:35:49.862000','Justin seems to be doing ok for now. Money is still tight, but he says he is content. It sounds like Justin is planning to stick around for awhile longer, after all. He just got a new barrel for his .300 Norma and spent last weekend shooting it, with fantastic results.','rmiller.contractor@m2fleetcom.com','jmclean.contractor@m2fleetcom.com','68ed0e45a9b8b46e7c0def6e','68a4fbc94354850115e95a02','{"note":"Justin seems to be doing ok for now. Money is still tight, but he says he is content. It sounds like Justin is planning to stick around for awhile longer, after all. He just got a new barrel for his .300 Norma and spent last weekend shooting it, with fantastic results.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"jmclean.contractor@m2fleetcom.com","callDate":"2025-10-13T14:35:49.145Z","technicianId":"68a4fbc94354850115e95a02","id":"68ed0e45a9b8b46e7c0def6e","created_date":"2025-10-13T14:35:49.862000","updated_date":"2025-10-13T14:35:49.862000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68daa9825e75f190ec0e3040'),'6457d94f-ba1c-4882-9939-991691035161','2025-09-29T15:45:06.691Z','Mark has been having some struggles getting started with Sunbelt. He has been over-thinking things, trying to be perfect, and it has been stressing him out a little bit. I reassured him that nobody is expecting full production, and that when he comes to a machine he has never seen before, he just needs to communicate that to his scheduling team. I got him pointed in the right direction for real-time tech support. Mark has shown some slowness in memory retention, but it is my opinion that he is just getting overwhelmed with all of the information being thrown at him. I think that Mark will be ok, once he has some time in service.','2025-09-29T15:45:06.927000','Mark has been having some struggles getting started with Sunbelt. He has been over-thinking things, trying to be perfect, and it has been stressing him out a little bit. I reassured him that nobody is expecting full production, and that when he comes to a machine he has never seen before, he just needs to communicate that to his scheduling team. I got him pointed in the right direction for real-time tech support. Mark has shown some slowness in memory retention, but it is my opinion that he is just getting overwhelmed with all of the information being thrown at him. I think that Mark will be ok, once he has some time in service.','rmiller.contractor@m2fleetcom.com','mburkett.contractor@m2fleetcom.com','68daa9825e75f190ec0e3040','68a88f7b0722d741fc6f5bb4','{"note":"Mark has been having some struggles getting started with Sunbelt. He has been over-thinking things, trying to be perfect, and it has been stressing him out a little bit. I reassured him that nobody is expecting full production, and that when he comes to a machine he has never seen before, he just needs to communicate that to his scheduling team. I got him pointed in the right direction for real-time tech support. Mark has shown some slowness in memory retention, but it is my opinion that he is just getting overwhelmed with all of the information being thrown at him. I think that Mark will be ok, once he has some time in service.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"mburkett.contractor@m2fleetcom.com","callDate":"2025-09-29T15:45:06.691Z","technicianId":"68a88f7b0722d741fc6f5bb4","id":"68daa9825e75f190ec0e3040","created_date":"2025-09-29T15:45:06.927000","updated_date":"2025-09-29T15:45:06.927000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68daa45f37ef0e866c77284f'),'6f9c8a7f-8993-4e0a-93f2-913c2d38df50','2025-09-29T15:23:11.374Z','Andres seems happy to be on Sunbelt and off of Velocal. He said he likes to travel and wants to see more of the country. All of the installs are new to him at this point, so he is taking his time working through them. He needs no instruction on how to effectively communicate delays to his schedulers, and has been able to find a pace that is keeping him at the same site for 2-3 days each.','2025-09-29T15:23:11.660000','Andres seems happy to be on Sunbelt and off of Velocal. He said he likes to travel and wants to see more of the country. All of the installs are new to him at this point, so he is taking his time working through them. He needs no instruction on how to effectively communicate delays to his schedulers, and has been able to find a pace that is keeping him at the same site for 2-3 days each.','rmiller.contractor@m2fleetcom.com','aarguello.contractor@smcinstallations.com','68daa45f37ef0e866c77284f','68a630e08f545166ef421612','{"note":"Andres seems happy to be on Sunbelt and off of Velocal. He said he likes to travel and wants to see more of the country. All of the installs are new to him at this point, so he is taking his time working through them. He needs no instruction on how to effectively communicate delays to his schedulers, and has been able to find a pace that is keeping him at the same site for 2-3 days each.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"aarguello.contractor@smcinstallations.com","callDate":"2025-09-29T15:23:11.374Z","technicianId":"68a630e08f545166ef421612","id":"68daa45f37ef0e866c77284f","created_date":"2025-09-29T15:23:11.660000","updated_date":"2025-09-29T15:23:11.660000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68daa3a38fa50a295fae854b'),'680cb20e-427b-411f-88c8-c0f420e29339','2025-09-29T15:20:02.820Z','John is doing much better now that he is back on Montage. He knows the product well, and now that he and Marshall are the only techs, he says everything is running smooth as glass. He has been happy to let Marshall deal with Craig and his team, while John gets to relax and focus on the installs. I will get him and Marshall out for lunch as soon as I can get access to the site again.','2025-09-29T15:20:03.621000','John is doing much better now that he is back on Montage. He knows the product well, and now that he and Marshall are the only techs, he says everything is running smooth as glass. He has been happy to let Marshall deal with Craig and his team, while John gets to relax and focus on the installs. I will get him and Marshall out for lunch as soon as I can get access to the site again.','rmiller.contractor@m2fleetcom.com','jwithrow.contractor@m2fleetcom.com','68daa3a38fa50a295fae854b','68a63a77cb05041249de3331','{"note":"John is doing much better now that he is back on Montage. He knows the product well, and now that he and Marshall are the only techs, he says everything is running smooth as glass. He has been happy to let Marshall deal with Craig and his team, while John gets to relax and focus on the installs. I will get him and Marshall out for lunch as soon as I can get access to the site again.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"jwithrow.contractor@m2fleetcom.com","callDate":"2025-09-29T15:20:02.820Z","technicianId":"68a63a77cb05041249de3331","id":"68daa3a38fa50a295fae854b","created_date":"2025-09-29T15:20:03.621000","updated_date":"2025-09-29T15:20:03.621000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68daa1f879fefc4acda45909'),'d9ef23f7-a77b-4e53-a3e6-9460d93ba148','2025-09-29T15:12:55.440Z','Marshall is doing well. He is back in his element out at Montage Walmart. He says that Craig and his team at Montage are running him around like crazy, but secretly I think he enjoys it. I am planning on visiting him on site when things calm down.','2025-09-29T15:12:56.215000','Marshall is doing well. He is back in his element out at Montage Walmart. He says that Craig and his team at Montage are running him around like crazy, but secretly I think he enjoys it. I am planning on visiting him on site when things calm down.','rmiller.contractor@m2fleetcom.com','mghilespi.contractor@m2fleetcom.com','68daa1f879fefc4acda45909','68ac80a7533b30793fd5e25b','{"note":"Marshall is doing well. He is back in his element out at Montage Walmart. He says that Craig and his team at Montage are running him around like crazy, but secretly I think he enjoys it. I am planning on visiting him on site when things calm down.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"mghilespi.contractor@m2fleetcom.com","callDate":"2025-09-29T15:12:55.440Z","technicianId":"68ac80a7533b30793fd5e25b","id":"68daa1f879fefc4acda45909","created_date":"2025-09-29T15:12:56.215000","updated_date":"2025-09-29T15:12:56.215000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68da9fe7f58d8b02542cdfdd'),'e43d6360-3d88-4783-9d5e-95d12ae05f76','2025-09-29T15:03:50.017Z','Robert is really enjoying the Vegas area. He mostly stays outside of the city where it is quiet. He is ready to get back into hiking with the weather cooling off. Robert did express some interest in changing to a different customer when his contract expires at the end of the year, but is in no hurry to make any changes currently.','2025-09-29T15:04:07.269000','Robert is really enjoying the Vegas area. He mostly stays outside of the city where it is quiet. He is ready to get back into hiking with the weather cooling off. Robert did express some interest in changing to a different customer when his contract expires at the end of the year, but is in no hurry to make any changes currently.','rmiller.contractor@m2fleetcom.com','rbuchanan.contractor@m2fleetcom.com','68da9fe7f58d8b02542cdfdd','68a63c13b06485574bc73e6b','{"note":"Robert is really enjoying the Vegas area. He mostly stays outside of the city where it is quiet. He is ready to get back into hiking with the weather cooling off. Robert did express some interest in changing to a different customer when his contract expires at the end of the year, but is in no hurry to make any changes currently.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"rbuchanan.contractor@m2fleetcom.com","callDate":"2025-09-29T15:03:50.017Z","technicianId":"68a63c13b06485574bc73e6b","id":"68da9fe7f58d8b02542cdfdd","created_date":"2025-09-29T15:04:07.269000","updated_date":"2025-09-29T15:04:07.269000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68da9e5becb8321c6f591c73'),'4a42b659-91c3-49ce-9b6d-14cbea1eb8bc','2025-09-29T14:57:25.279Z','Rance is in good spirits, despite having some initial struggles with Victorinox. He has been unable to access most of the guides that he needs on his phone, and Velociti has had some difficulty in getting the issue resolved. As a result, he has been working some very long nights, just trying to get the job done. We got him paired up with Donald White on the velo side to get emailed copies of the first articles he needs. I will continue to monitor.','2025-09-29T14:57:31.921000','Rance is in good spirits, despite having some initial struggles with Victorinox. He has been unable to access most of the guides that he needs on his phone, and Velociti has had some difficulty in getting the issue resolved. As a result, he has been working some very long nights, just trying to get the job done. We got him paired up with Donald White on the velo side to get emailed copies of the first articles he needs. I will continue to monitor.','rmiller.contractor@m2fleetcom.com','ramiller.contractor@m2fleetcom.com','68da9e5becb8321c6f591c73','68a63bd2ccc87b9523363bc6','{"note":"Rance is in good spirits, despite having some initial struggles with Victorinox. He has been unable to access most of the guides that he needs on his phone, and Velociti has had some difficulty in getting the issue resolved. As a result, he has been working some very long nights, just trying to get the job done. We got him paired up with Donald White on the velo side to get emailed copies of the first articles he needs. I will continue to monitor.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"ramiller.contractor@m2fleetcom.com","callDate":"2025-09-29T14:57:25.279Z","technicianId":"68a63bd2ccc87b9523363bc6","id":"68da9e5becb8321c6f591c73","created_date":"2025-09-29T14:57:31.921000","updated_date":"2025-09-29T14:57:31.921000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68da9d1aa914ebf254d0f5db'),'79a2f92c-2fcb-4513-bea9-dd330470cb3c','2025-09-29T14:52:09.876Z','Victor is in good spirits. His shoulder is much better and he is having no trouble keeping up again. He is looking forward to flying home soon to visit his family.','2025-09-29T14:52:10.094000','Victor is in good spirits. His shoulder is much better and he is having no trouble keeping up again. He is looking forward to flying home soon to visit his family.','rmiller.contractor@m2fleetcom.com','vmendoza.contractor@m2fleetcom.com','68da9d1aa914ebf254d0f5db','68a901f089d2da1c8599b94f','{"note":"Victor is in good spirits. His shoulder is much better and he is having no trouble keeping up again. He is looking forward to flying home soon to visit his family.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"vmendoza.contractor@m2fleetcom.com","callDate":"2025-09-29T14:52:09.876Z","technicianId":"68a901f089d2da1c8599b94f","id":"68da9d1aa914ebf254d0f5db","created_date":"2025-09-29T14:52:10.094000","updated_date":"2025-09-29T14:52:10.094000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68cee1f2eb84ca24854d1754'),'62ea6113-66e9-4621-8eb6-a025a45659d8','2025-09-20T17:18:41.951Z','Spoke with him today, is asking if he can be considered a travel tech and stay where he is. As he doesn''t like being at 1100. says when he travels to Abilene and other places the extra 100 dollars doesn''t cover gas and food, and he loses money.  I told him we will work on it but I couldn''t give him a definitive answer today.','2025-09-20T17:18:42.297000','Spoke with him today, is asking if he can be considered a travel tech and stay where he is. As he doesn''t like being at 1100. says when he travels to Abilene and other places the extra 100 dollars doesn''t cover gas and food, and he loses money.  I told him we will work on it but I couldn''t give him a definitive answer today.','austin@m2fleetcom.com','zmclarry.contractor@m2fleetcom.com','68cee1f2eb84ca24854d1754','68add701a9a4a405aeb6928e','{"note":"Spoke with him today, is asking if he can be considered a travel tech and stay where he is. As he doesn''t like being at 1100. says when he travels to Abilene and other places the extra 100 dollars doesn''t cover gas and food, and he loses money.  I told him we will work on it but I couldn''t give him a definitive answer today.","loggedBy":"austin@m2fleetcom.com","technicianEmail":"zmclarry.contractor@m2fleetcom.com","callDate":"2025-09-20T17:18:41.951Z","technicianId":"68add701a9a4a405aeb6928e","id":"68cee1f2eb84ca24854d1754","created_date":"2025-09-20T17:18:42.297000","updated_date":"2025-09-20T17:18:42.297000","created_by_id":"68a390239868be00767c8ae9","created_by":"austin@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68c74d4c2f3ffcc05dcff19d'),'b272067e-4446-4c50-9fb2-ed75bd3a4e6c','2025-09-14T23:18:36.745Z','Leon has been doing well. He said he enjoyed Samsara, but is ready for something new. I gave him a pregame chat about what to expect out on his next contract, Mr Greens Produce.','2025-09-14T23:18:36.899000','Leon has been doing well. He said he enjoyed Samsara, but is ready for something new. I gave him a pregame chat about what to expect out on his next contract, Mr Greens Produce.','rmiller.contractor@m2fleetcom.com','lhernandez.contractor@m2fleetcom.com','68c74d4c2f3ffcc05dcff19d','68a63b24c212997a469ce950','{"note":"Leon has been doing well. He said he enjoyed Samsara, but is ready for something new. I gave him a pregame chat about what to expect out on his next contract, Mr Greens Produce.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"lhernandez.contractor@m2fleetcom.com","callDate":"2025-09-14T23:18:36.745Z","technicianId":"68a63b24c212997a469ce950","id":"68c74d4c2f3ffcc05dcff19d","created_date":"2025-09-14T23:18:36.899000","updated_date":"2025-09-14T23:18:36.899000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68c74cc7b3e5b2f2b739cdaf'),'ed407e96-8f22-4d32-8af9-558de6d5ced1','2025-09-14T23:16:23.454Z','Jose is enjoying Victorinox. He''s been on a few other contracts where he actually has to work for his money, and has really come to appreciate how easy the job is. He is looking forward to seeing what Minnesota looks like in the fall, but sounds like he would be happy closer to home if the opportunity pops up.','2025-09-14T23:16:23.631000','Jose is enjoying Victorinox. He''s been on a few other contracts where he actually has to work for his money, and has really come to appreciate how easy the job is. He is looking forward to seeing what Minnesota looks like in the fall, but sounds like he would be happy closer to home if the opportunity pops up.','rmiller.contractor@m2fleetcom.com','jmendoza.contractor@m2fleetcom.com','68c74cc7b3e5b2f2b739cdaf','68a63a916936de7b29edcfb8','{"note":"Jose is enjoying Victorinox. He''s been on a few other contracts where he actually has to work for his money, and has really come to appreciate how easy the job is. He is looking forward to seeing what Minnesota looks like in the fall, but sounds like he would be happy closer to home if the opportunity pops up.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"jmendoza.contractor@m2fleetcom.com","callDate":"2025-09-14T23:16:23.454Z","technicianId":"68a63a916936de7b29edcfb8","id":"68c74cc7b3e5b2f2b739cdaf","created_date":"2025-09-14T23:16:23.631000","updated_date":"2025-09-14T23:16:23.631000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68c74b3e74f6ba660e683cba'),'361e055a-2bcb-42f8-b9be-d308dbdd9cc6','2025-09-14T23:09:50.867Z','Kameron is still trucking along. He doesn''t enjoy SBR anymore, but doesn''t want a different contract and continues to do good work. He has discussed moving to Houston towards the end of the year. While I don''t think we will have an open SBR spot down there, or that he would take it if we did, but I have discussed some of the Amazon jobs with Kameron, which seemed to pique his interest.','2025-09-14T23:09:50.838000','Kameron is still trucking along. He doesn''t enjoy SBR anymore, but doesn''t want a different contract and continues to do good work. He has discussed moving to Houston towards the end of the year. While I don''t think we will have an open SBR spot down there, or that he would take it if we did, but I have discussed some of the Amazon jobs with Kameron, which seemed to pique his interest.','rmiller.contractor@m2fleetcom.com','kmartineau.contractor@m2fleetcom.com','68c74b3e74f6ba660e683cba','68a63ae9cb05041249de338e','{"note":"Kameron is still trucking along. He doesn''t enjoy SBR anymore, but doesn''t want a different contract and continues to do good work. He has discussed moving to Houston towards the end of the year. While I don''t think we will have an open SBR spot down there, or that he would take it if we did, but I have discussed some of the Amazon jobs with Kameron, which seemed to pique his interest.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"kmartineau.contractor@m2fleetcom.com","callDate":"2025-09-14T23:09:50.867Z","technicianId":"68a63ae9cb05041249de338e","id":"68c74b3e74f6ba660e683cba","created_date":"2025-09-14T23:09:50.838000","updated_date":"2025-09-14T23:09:50.838000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68c74a85a0955b303b7f9196'),'0ea4bdb1-b8ec-4771-81a7-b1ba2e312dd7','2025-09-14T23:06:45.340Z','Ray is happy to be back on SBR. While availability isn''t as bad as DFW, he is having more trouble finding equipment to work on again. There are a few other products and services that velociti offers to SBR, but Ray isn''t trained up on  them. The services are definitely out there in his area, and he is ready and capable of learning how to do them. I will bring this up with the trainers at velociti.','2025-09-14T23:06:45.472000','Ray is happy to be back on SBR. While availability isn''t as bad as DFW, he is having more trouble finding equipment to work on again. There are a few other products and services that velociti offers to SBR, but Ray isn''t trained up on  them. The services are definitely out there in his area, and he is ready and capable of learning how to do them. I will bring this up with the trainers at velociti.','rmiller.contractor@m2fleetcom.com','rbustamante.contractor@m2fleetcom.com','68c74a85a0955b303b7f9196','68a63bf16e5b61a47075febc','{"note":"Ray is happy to be back on SBR. While availability isn''t as bad as DFW, he is having more trouble finding equipment to work on again. There are a few other products and services that velociti offers to SBR, but Ray isn''t trained up on  them. The services are definitely out there in his area, and he is ready and capable of learning how to do them. I will bring this up with the trainers at velociti.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"rbustamante.contractor@m2fleetcom.com","callDate":"2025-09-14T23:06:45.340Z","technicianId":"68a63bf16e5b61a47075febc","id":"68c74a85a0955b303b7f9196","created_date":"2025-09-14T23:06:45.472000","updated_date":"2025-09-14T23:06:45.472000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68c749ceaca445bc987f2a74'),'fe33d54c-9c91-4fd9-a988-8e5992fc9489','2025-09-14T23:03:42.504Z','Erik is doing well. He is much more happy back on SBR than he was on Texas First Rentals. They''ve had him doing a lot of proximity lights again, which he loves, because he gets to work in a shop with a giant fan and a dedicated workstation, and the installs themselves are very easy for him.','2025-09-14T23:03:42.748000','Erik is doing well. He is much more happy back on SBR than he was on Texas First Rentals. They''ve had him doing a lot of proximity lights again, which he loves, because he gets to work in a shop with a giant fan and a dedicated workstation, and the installs themselves are very easy for him.','rmiller.contractor@m2fleetcom.com','ebaltazar.contractor@m2fleetcom.com','68c749ceaca445bc987f2a74','68a6390dc778ad7fe6452705','{"note":"Erik is doing well. He is much more happy back on SBR than he was on Texas First Rentals. They''ve had him doing a lot of proximity lights again, which he loves, because he gets to work in a shop with a giant fan and a dedicated workstation, and the installs themselves are very easy for him.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"ebaltazar.contractor@m2fleetcom.com","callDate":"2025-09-14T23:03:42.504Z","technicianId":"68a6390dc778ad7fe6452705","id":"68c749ceaca445bc987f2a74","created_date":"2025-09-14T23:03:42.748000","updated_date":"2025-09-14T23:03:42.748000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68c747a8354a15c673694f9c'),'26775328-6604-4ea5-a0d9-f0f91ecebf80','2025-09-14T22:54:32.451Z','Carlos was in a good mood, as per usual when I talk to him. He knows the installs, knows the area, and knows the scheduling team well, and has really settled into a routine on PCT. He loves the job, but is ready for cooler weather to come back.','2025-09-14T22:54:32.578000','Carlos was in a good mood, as per usual when I talk to him. He knows the installs, knows the area, and knows the scheduling team well, and has really settled into a routine on PCT. He loves the job, but is ready for cooler weather to come back.','rmiller.contractor@m2fleetcom.com','crincon.contractor@m2fleetcom.com','68c747a8354a15c673694f9c','68a6384a1137f6d80a596631','{"note":"Carlos was in a good mood, as per usual when I talk to him. He knows the installs, knows the area, and knows the scheduling team well, and has really settled into a routine on PCT. He loves the job, but is ready for cooler weather to come back.","loggedBy":"rmiller.contractor@m2fleetcom.com","technicianEmail":"crincon.contractor@m2fleetcom.com","callDate":"2025-09-14T22:54:32.451Z","technicianId":"68a6384a1137f6d80a596631","id":"68c747a8354a15c673694f9c","created_date":"2025-09-14T22:54:32.578000","updated_date":"2025-09-14T22:54:32.578000","created_by_id":"68a6388cc778ad7fe64526ca","created_by":"rmiller.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
