INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68b8822fe2a1c9218a86e18a'),'453fa56b-01c0-4457-be94-fe89bcd95e74','2025-09-03T18:00:15.139Z','He seemed very happy with his current situation. He said he was building a good rapport with his AMR PM and they want him on the phase 2 of the project next year. He said they are headed to Houston on Friday and he is looking forward to that. He is getting along with everyone on the Velo side and was in very good spirits. Had a good conversation.','2025-09-03T18:00:15.298000','He seemed very happy with his current situation. He said he was building a good rapport with his AMR PM and they want him on the phase 2 of the project next year. He said they are headed to Houston on Friday and he is looking forward to that. He is getting along with everyone on the Velo side and was in very good spirits. Had a good conversation.','choffman.contractor@m2fleetcom.com','jtran.contractor@m2fleetcom.com','68b8822fe2a1c9218a86e18a','68a63a68217a039a0fc96c61','{"note":"He seemed very happy with his current situation. He said he was building a good rapport with his AMR PM and they want him on the phase 2 of the project next year. He said they are headed to Houston on Friday and he is looking forward to that. He is getting along with everyone on the Velo side and was in very good spirits. Had a good conversation.","loggedBy":"choffman.contractor@m2fleetcom.com","technicianEmail":"jtran.contractor@m2fleetcom.com","callDate":"2025-09-03T18:00:15.139Z","technicianId":"68a63a68217a039a0fc96c61","id":"68b8822fe2a1c9218a86e18a","created_date":"2025-09-03T18:00:15.298000","updated_date":"2025-09-03T18:00:15.298000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
INSERT INTO public."CallLog" (id,"technicianId","callDate",notes,created_at,note,"loggedBy","technicianEmail",legacy_id,legacy_technician_id,metadata,source_system) VALUES (public.m2_legacy_uuid('CallLog:68b8818edbed78573fac15f9'),'b272067e-4446-4c50-9fb2-ed75bd3a4e6c','2025-09-03T17:57:33.788Z','Currently in Alabama, and still doing very well with everything. He has no complaints for his current job. He mentioned he was requested to do a 3 week job in Dallas following his current contract, and is looking forward to learning something new. The only issue he had is wanting to make sure he can find a way to get some time in between jobs to see family back home, said he may end up trying to take off a week or 2 in the near future if needed. He’s always in good spirits and never has any real complaints.','2025-09-03T17:57:34.152000','Currently in Alabama, and still doing very well with everything. He has no complaints for his current job. He mentioned he was requested to do a 3 week job in Dallas following his current contract, and is looking forward to learning something new. The only issue he had is wanting to make sure he can find a way to get some time in between jobs to see family back home, said he may end up trying to take off a week or 2 in the near future if needed. He’s always in good spirits and never has any real complaints.','choffman.contractor@m2fleetcom.com','lhernandez.contractor@m2fleetcom.com','68b8818edbed78573fac15f9','68a63b24c212997a469ce950','{"note":"Currently in Alabama, and still doing very well with everything. He has no complaints for his current job. He mentioned he was requested to do a 3 week job in Dallas following his current contract, and is looking forward to learning something new. The only issue he had is wanting to make sure he can find a way to get some time in between jobs to see family back home, said he may end up trying to take off a week or 2 in the near future if needed. He\u2019s always in good spirits and never has any real complaints.","loggedBy":"choffman.contractor@m2fleetcom.com","technicianEmail":"lhernandez.contractor@m2fleetcom.com","callDate":"2025-09-03T17:57:33.788Z","technicianId":"68a63b24c212997a469ce950","id":"68b8818edbed78573fac15f9","created_date":"2025-09-03T17:57:34.152000","updated_date":"2025-09-03T17:57:34.152000","created_by_id":"68a63874fca958620f9e640e","created_by":"choffman.contractor@m2fleetcom.com","is_sample":"false"}','Base44 export') ON CONFLICT DO NOTHING;
